

CREATE TABLE `account_setting` (
  `account_id` int(11) NOT NULL AUTO_INCREMENT,
  `cashopeningbal` float NOT NULL,
  `bankopeningbal` float NOT NULL,
  `open_bal_date` date NOT NULL,
  `office_opening_bal` float NOT NULL,
