  `updated_date` date NOT NULL,
  `user_id` int(11) NOT NULL,
  PRIMARY KEY (`account_id`)
) ENGINE=MyISAM AUTO_INCREMENT=7 DEFAULT CHARSET=latin1;




CREATE TABLE `attendance` (
  `attendid` int(11) NOT NULL AUTO_INCREMENT,
